'use strict';
const $ = s => document.querySelector(s);
const esc = s => String(s ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={back:'m14 5-7 7 7 7',chevron:'m9 5 7 7-7 7',check:'m5 12 4 4L19 6',shield:'M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6l-8-3Z|m8 12 3 3 5-6',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3Z',home:'m3 10 9-7 9 7|M5 9v12h5v-7h4v7h5V9',calendar:'M5 5h14v16H5z|M8 3v4|M16 3v4|M5 10h14',user:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0Z|M4 21v-2a8 8 0 0 1 16 0v2',search:'M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0Z|m15 15 6 6',pin:'M19 9c0 6-7 12-7 12S5 15 5 9a7 7 0 1 1 14 0Z|M14 9a2 2 0 1 1-4 0 2 2 0 0 1 4 0Z',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0Z|M12 7v5l3 2',star:'m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2L12 17.3 6.4 20.2l1.1-6.2L3 9.6l6.2-.9L12 3Z',chat:'M21 11a8 8 0 0 1-8 8H5l-3 3V11a9 9 0 0 1 19 0Z|M7 10h10|M7 14h6',call:'M5 3h4l2 5-3 2a13 13 0 0 0 6 6l2-3 5 2v4c0 2-3 3-5 2A21 21 0 0 1 3 8c-1-2 0-5 2-5Z',info:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0Z|M12 11v6|M12 7v1',camera:'M3 7h4l2-3h6l2 3h4v14H3V7Z|M16 13a4 4 0 1 1-8 0 4 4 0 0 1 8 0Z',tool:'M21 3a6 6 0 0 0-7 8L4 21l-3-3L11 8a6 6 0 0 0 8-7l-4 4 4 2 2-4Z',drop:'M12 2S4 11 4 15a8 8 0 0 0 16 0c0-4-8-13-8-13Z',washer:'M4 3h16v19H4z|M4 7h16|M16 14a4 4 0 1 1-8 0 4 4 0 0 1 8 0Z|M7 5h1|M10 5h1',rotate:'M20 7v5h-5|M4 17v-5h5|M5 8a8 8 0 0 1 13-3l2 4|M19 16a8 8 0 0 1-13 3l-2-4',volume:'M4 9h4l5-4v14l-5-4H4V9Z|M17 8a6 6 0 0 1 0 8|M20 5a10 10 0 0 1 0 14',power:'M12 2v10|M6 5a9 9 0 1 0 12 0',download:'M12 3v12|m7 10 5 5 5-5|M4 17v4h16v-4',close:'m6 6 12 12|m6 18 12-12',list:'M9 5h12|M9 12h12|M9 19h12|M3 5h1|M3 12h1|M3 19h1',battery:'M3 7h16v10H3z|M21 10v4|M5 9h11v6H5z',signal:'M4 20v-4|M9 20v-8|M14 20V8|M19 20V4',wifi:'M3 8a15 15 0 0 1 18 0|M6 12a10 10 0 0 1 12 0|M9 16a5 5 0 0 1 6 0|M12 20h.01',file:'M5 3h9l5 5v13H5V3Z|M14 3v5h5|M8 12h8|M8 16h6',money:'M3 5h18v14H3z|M14 12a2 2 0 1 1-4 0 2 2 0 0 1 4 0Z|M6 8h1|M17 16h1'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${(paths[name]||paths.info).split('|').map(p=>`<path d="${p}"/>`).join('')}</svg>`;
const button=(text,action,style='',disabled=false)=>`<button class="btn ${style}" data-action="${action}" ${disabled?'disabled':''}>${text}</button>`;
const badge=(text,color='',ico)=>`<span class="badge ${color}">${ico?icon(ico):''}${text}</span>`;
const checks=[['Drain filter inspected','Blocked by lint and debris','Issue found'],['Drain pump output tested','Output below expected range','Issue found'],['Outlet hose inspected','Visible crack near the connector','Issue found'],['Drain pipe checked','No external blockage found','Passed'],['Control-panel error checked','OE drainage error recorded','Issue found'],['Drum rotation tested','Working normally','Passed']];
const evidenceSeed=[{title:'Blocked drain filter',check:0,time:'10:42 AM',description:'Lint and debris are visibly blocking the drain filter.',type:'photo',clear:true},{title:'Damaged outlet hose',check:2,time:'10:46 AM',description:'A visible crack is present near the hose connector.',type:'photo',clear:true},{title:'Pump-output reading',check:1,time:'10:49 AM',description:'Measured flow: 4 L/min. Technician reference range: 8–12 L/min.',limitation:'This reading identifies reduced output but does not independently identify the exact cause.',type:'reading',clear:true},{title:'OE drainage error',check:4,time:'10:52 AM',description:'The control panel displayed the OE drainage error during the inspection.',limitation:'An error code indicates a drainage problem; it does not confirm which component caused it.',type:'code',clear:true}];
const summaryConfirmed='Your washing machine is unable to drain water properly because the drain filter is blocked and the outlet hose is damaged. The pump is still functioning, but its output is below the expected range.';
const summaryLikely='The professional measured reduced pump output. This may indicate reduced pump efficiency, but the cause has not been confirmed. A further test after cleaning is required before deciding whether any pump repair is needed.';
const summaryUnverified='The professional could not reproduce or confirm the reported drainage issue. Additional inspection is required before recommending repair.';
const base=()=>({role:'customer',screen:'home',booked:false,submitted:false,customerStatus:'Not viewed',approved:false,repairStarted:false,completed:false,expert:'none',certainty:'Confirmed',certaintyReason:'Supported by filter inspection, pump-output reading, visible hose damage and recorded drainage error.',recommend:'Repair',checkStatus:['Issue found','Issue found','Issue found','Passed','',''],checkReasons:{},observations:{},evidence:structuredClone(evidenceSeed),summary:'',reviewed:false,quoteCreated:false,prices:[499,600],links:[true,true],revised:false,revision:1,approvedRevision:null,history:[],date:'12 Oct',slot:'10:00–11:00 AM',symptoms:[true,true,false,true],service:'Not draining',rating:0,declineReason:'',finishedAt:''});
let state;try{state={...base(),...JSON.parse(localStorage.getItem('uc-trust-v1')||'null')}}catch{state=base()}
let mapOpen=false,expanded=new Set(),quoteExpanded=new Set(),sheet=null,assistLanguage='English',assistQuestion=null,busy=false,toastTimer;
function save(){try{localStorage.setItem('uc-trust-v1',JSON.stringify(state))}catch{toast('Storage is full. Your session is still available.')}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200)}
function go(screen){state.history.push({screen:state.screen,role:state.role});state.screen=screen;save();render();$('.content')?.scrollTo(0,0)}
function back(){let prev=state.history.pop();while(prev&&prev.role!==state.role)prev=state.history.pop();if(prev){state.screen=prev.screen;save();render()}else go(state.role==='customer'?'home':'assigned')}
const total=()=>249+state.prices.reduce((a,b)=>a+Number(b),0);
const money=n=>'₹'+Number(n).toLocaleString('en-IN');
const allChecks=()=>state.checkStatus.every((s,i)=>s&& (s!=='Could not verify'||(state.checkReasons[i]||'').trim().length>5));
function validations(){const hasCheck=i=>state.evidence.some(e=>e.check===i&&e.clear);const unsupported=state.certainty==='Confirmed'?(state.links.some(v=>!v)||state.recommend!=='Repair'):(state.quoteCreated||state.recommend!=='Additional inspection required');return[{label:'Required checks completed',ok:allChecks()},{label:'Finding supported by clear evidence',ok:[0,1,2,4].every(hasCheck)},{label:'Certainty explained',ok:state.certaintyReason.trim().length>12},{label:'Customer-friendly summary generated',ok:!!state.summary.trim()},{label:'No unsupported repair items detected',ok:!unsupported},{label:'No contradictory findings',ok:[0,1,2,4].every(i=>state.checkStatus[i]==='Issue found')&& !/(?:replace|replacement|replacing)[^.]*pump|pump[^.]*(?:replace|replacement|replacing)/i.test(state.summary) && !(state.certainty!=='Confirmed'&&/\bconfirmed\b|definitely|certainly/i.test(state.summary.replace(/(?:not|not fully|not been|not yet) confirmed/gi,'unverified')))},{label:'UC Assist summary reviewed by professional',ok:state.reviewed}]}
const canSubmit=()=>(state.quoteCreated||state.certainty!=='Confirmed')&&validations().every(v=>v.ok);
const canRepair=()=>state.approved&&state.approvedRevision===state.revision&&!state.completed;
function washerArt(){return `<svg class="washer" viewBox="0 0 160 210" aria-label="Front-load washing machine illustration" role="img"><defs><linearGradient id="body" x1="0" x2="1"><stop stop-color="#d8d8db"/><stop offset=".4" stop-color="#fafafb"/><stop offset="1" stop-color="#cfcdd4"/></linearGradient><linearGradient id="glass" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#383740"/><stop offset="1" stop-color="#13131b"/></linearGradient></defs><path d="M23 13 136 20l7 172-121-2Z" fill="#a7a5af"/><rect x="14" y="12" width="121" height="184" rx="7" fill="url(#body)"/><path d="M16 46h116" stroke="#c4c2ca"/><rect x="24" y="24" width="42" height="10" rx="2" fill="#eeeef0" stroke="#b5b2bc"/><circle cx="83" cy="31" r="7" fill="#a5a3ad" stroke="#f6f6f8" stroke-width="3"/><rect x="101" y="25" width="25" height="11" rx="2" fill="#302d38"/><text x="105" y="33" fill="#bfd1cf" font-size="6">0:45</text><circle cx="75" cy="110" r="48" fill="#b7b4bf"/><circle cx="75" cy="110" r="42" fill="#eeeef0"/><circle cx="75" cy="110" r="34" fill="url(#glass)"/><path d="M50 90q20-16 44 7l-5 33q-29 12-39-7Z" fill="#77727e" opacity=".5"/><path d="M48 89q19-19 42-7" fill="none" stroke="#fff" stroke-width="3" opacity=".25"/><rect x="23" y="174" width="102" height="4" rx="2" fill="#b8b6bf"/><rect x="101" y="156" width="23" height="12" rx="3" fill="#dad8df" stroke="#c4c1cb"/></svg>`}
function avatar(){return `<div class="avatar"><svg viewBox="0 0 48 48" role="img" aria-label="Arjun Kumar illustrated profile"><rect width="48" height="48" fill="#eee4d8"/><path d="M6 48c0-13 10-20 18-20s18 7 18 20" fill="#484458"/><path d="m20 28-1 7 5 4 6-4-2-8" fill="#bc886b"/><ellipse cx="24" cy="19" rx="10" ry="13" fill="#cc9b7a"/><path d="M14 17V9c2-7 18-7 20 2v6l-5-8c-4 4-8 4-15 5Z" fill="#302827"/><path d="M16 23c2 8 13 9 16-1l-4 4h-8Z" fill="#5b3d32"/><path d="M20 18h1m7 0h1" stroke="#302827" stroke-width="2" stroke-linecap="round"/></svg></div>`}
function evidenceArt(e){if(e.url&&e.type==='video')return `<video src="${esc(e.url)}" controls playsinline aria-label="${esc(e.title)}" style="width:100%;height:100%;object-fit:contain"></video>`;if(e.url)return `<img src="${esc(e.url)}" alt="${esc(e.title)}">`;let art='';if(e.type==='reading')art=`<rect width="180" height="110" fill="#e5e8e6"/><rect x="44" y="12" width="94" height="93" rx="10" fill="#414b43"/><rect x="52" y="23" width="78" height="43" rx="4" fill="#d4ddc7"/><text x="91" y="44" text-anchor="middle" font-family="monospace" font-size="18" fill="#354638">4.0</text><text x="91" y="58" text-anchor="middle" font-size="8" fill="#45553e">L / MIN</text><circle cx="70" cy="82" r="8" fill="#e0a34a"/><circle cx="108" cy="82" r="8" fill="#859079"/>`;else if(e.type==='code')art=`<rect width="180" height="110" fill="#c8c6c9"/><path d="M0 26h180v57H0" fill="#e1e0e3"/><rect x="32" y="35" width="115" height="40" rx="4" fill="#26252b"/><text x="88" y="65" text-anchor="middle" font-family="monospace" font-size="31" fill="#b8d2b8">OE</text><circle cx="14" cy="55" r="9" fill="#aaa7b0"/>`;else if(e.check===2)art=`<rect width="180" height="110" fill="#b6b5ad"/><path d="M-10 89c47-11 83-76 113-44s35 8 84 0" fill="none" stroke="#777a72" stroke-width="27"/><path d="M-10 89c47-11 83-76 113-44s35 8 84 0" fill="none" stroke="#a5a79d" stroke-width="22" stroke-dasharray="3 3"/><path d="m100 41 8 15-10 8 12 8" stroke="#45483e" stroke-width="3" fill="none"/><circle cx="105" cy="55" r="23" fill="none" stroke="#f3c374" stroke-width="1.5"/>`;else art=`<rect width="180" height="110" fill="#bebbb1"/><ellipse cx="90" cy="59" rx="57" ry="45" fill="#555851"/><ellipse cx="90" cy="59" rx="46" ry="34" fill="#898c79"/><path d="m56 50 54 28M53 61l54-17M68 32l16 58M100 32 91 87" stroke="#454c3c" stroke-width="5"/><path d="m61 44 23 13 28-11-4 22-30 7-21-14Z" fill="#6c604b"/><path d="m64 48 17 3 12 16m-20-7 34-4" fill="none" stroke="#b1a07b" stroke-width="4"/><circle cx="90" cy="58" r="32" fill="none" stroke="#f3c374" stroke-width="1.5"/>`;return `<svg viewBox="0 0 180 110" role="img" aria-label="Illustrative demo: ${esc(e.title)}">${art}</svg>`}
function profile(){return `<div class="row profile">${avatar()}<div class="grow"><h3>Arjun Kumar ${badge('UC verified','green','shield')}</h3><div class="small">${icon('star')} <b>4.82</b> <span class="muted"> · 1,240 jobs completed</span></div></div></div>`}
function assistCard(quote=false){return `<div class="card purple assist"><div class="assist-header">${icon('spark')}${quote?'UC Assist summary':'Explained with UC Assist'}</div><p>${quote?'The available evidence supports cleaning the drainage system and replacing the damaged hose. The machine’s drum and control functions passed their checks, so no additional repair is currently recommended.':esc(state.summary||summaryConfirmed)+(state.certainty==='Confirmed'?' Cleaning the drainage system and replacing the damaged hose should restore normal drainage.':'')}</p>${quote?`<div class="chips">${badge('Recommendation confidence: High','green')}${badge('Evidence linked','green')}</div><div class="tiny muted">This summary explains the quotation. Final diagnosis and repair decisions remain with the professional and customer.</div>`:`<div class="tiny muted">Based on professional checks and uploaded evidence.<br>AI helps explain findings; the professional records the diagnosis.</div>`}<div class="reviewed">${icon('shield')} Reviewed by Arjun Kumar</div></div>`}
function evidenceCards(){return `<div class="evidence-grid">${state.evidence.map((e,i)=>`<button class="evidence-card" data-action="evidence:${i}"><div class="evidence-art">${evidenceArt(e)}</div><div class="evidence-copy"><b>${esc(e.title)}</b><span>${esc(e.time)} · By Arjun</span><span>${esc(checks[e.check][0])}</span><span class="link">View evidence ${icon('chevron')}</span></div></button>`).join('')}</div>`}
function findingCard(){const c=state.certainty,likely=c==='Likely';return `<div class="card ${c==='Confirmed'?'green':'amber'} finding"><div class="row between"><span class="eyebrow">Overall finding</span><button data-action="certainty-info">${badge(c,c==='Confirmed'?'green':'amber',c==='Confirmed'?'check':'info')}</button></div><h3>${c==='Confirmed'?'Drain filter blockage with reduced pump output and damaged outlet hose.':likely?'Drain pump may be losing efficiency.':'Drainage issue could not be verified.'}</h3>${c!=='Confirmed'?`<p>${likely?'The available checks suggest reduced pump efficiency, but the cause could not be fully confirmed during the visit.':'The reported issue could not be reproduced or confirmed during the visit.'}</p>`:''}<div class="recommend"><div class="tiny muted">RECOMMENDED NEXT STEP</div><p class="bold">${c==='Confirmed'?'Clean the drain system and replace the damaged outlet hose.':'Additional inspection required before approving a repair.'}</p></div></div>`}
function checksCard(){return `<div class="card checks-card">${checks.map((c,i)=>`<div class="check-row"><button data-action="expand:${i}" aria-expanded="${expanded.has(i)}">${icon('check','check-icon')}<span class="check-text">${c[0]}<small>${state.checkStatus[i]==='Could not verify'?'Could not verify':c[1]}</small></span>${icon('chevron','chevron')}</button>${expanded.has(i)?`<div class="check-detail">${esc(state.observations[i]||c[1])}. ${state.checkStatus[i]==='Could not verify'?esc(state.checkReasons[i]):'Completed by Arjun Kumar during the inspection.'}<br>${state.evidence.filter(e=>e.check===i).length?'Supporting evidence is available below.':'Recorded as a visual / functional check.'}</div>`:''}</div>`).join('')}</div>`}
function quoteItems(edit=false){return ['Drain pump and filter cleaning','Outlet hose replacement'].map((name,i)=>`<div class="card"><div class="row between start"><div class="quote-title">${name}</div>${edit?`<div>₹ <input class="quote-input" type="number" min="1" max="99999" step="1" data-price="${i}" aria-label="${name} price" value="${state.prices[i]}"></div>`:`<div class="price">${money(state.prices[i])}</div>`}</div><div style="margin-top:7px">${badge('UC rate card','purple','shield')}</div><div class="reason">${icon('check')} ${i===0?'Blockage found in the drain filter and reduced pump output':'Visible crack found near the hose connector'}</div>${edit?`<label class="checkbox"><input type="checkbox" data-link="${i}" ${state.links[i]?'checked':''}>Link finding, completed check and ${i===0?'filter photo + pump reading':'hose photo'}</label>`:`<div class="quote-links"><button class="link" data-action="quote-expand:${i}">Why is this needed?</button><button class="link" data-action="linked:${i}">${icon('camera')} View linked evidence</button></div>`}${quoteExpanded.has(i)?`<p class="muted small">${i===0?'The technician will remove accumulated lint and debris, clean the filter and drainage system, and retest water flow. This quote does not include pump replacement.':'The cracked outlet hose will be replaced and the connection checked for leaks. Includes the replacement hose and fitting.'}</p>`:''}<div class="row small muted">${icon('shield')} 30-day service warranty</div></div>`).join('')}
function totals(){return `<div class="card"><div class="info-row"><span>Repair services</span><span>${money(total()-249)}</span></div><div class="info-row"><span>Inspection fee</span><span>₹249</span></div><div class="row between total"><b>Total payable</b><span class="price">${money(total())}</span></div><div class="row between small muted" style="margin-top:12px"><span>${icon('clock')} 45 minutes</span><span>${icon('shield')} 30-day warranty</span></div></div>`}
const step=n=>`<div class="step-indicator">${Array.from({length:6},(_,i)=>`<span class="${i<n?'on':''}"></span>`).join('')}</div><div class="eyebrow">Inspection · Step ${n} of 6</div>`;
let footer='',nav=false;
function page(){footer='';nav=false;const s=state.screen;switch(s){
case 'home':nav=true;footer=button('Continue '+icon('chevron'),'go:select');return `<div class="page white"><div class="search">${icon('search')}<input id="search" aria-label="Search services" placeholder="Search for a service"></div><div class="hero"><div class="hero-copy"><div class="eyebrow" style="color:#7c5caf;letter-spacing:1px">Expert care at home</div><h1>Washing Machine<br>Repair</h1><div class="small muted">Back to laundry.<br>Without the guesswork.</div><div style="margin-top:16px">${badge('★ 4.82 · Trusted professionals','purple')}</div></div>${washerArt()}</div><div class="benefits"><div>${icon('shield')}<br>UC verified<br>professionals</div><div>${icon('money')}<br>Transparent<br>pricing</div><div>${icon('calendar')}<br>30-day service<br>warranty</div></div><div class="row between"><h3 class="section-title">What do you need help with?</h3></div><div class="options-grid">${['Washing machine check-up','Water leakage','Not draining','Not spinning','Unusual noise','Not powering on'].map((t,i)=>`<button class="service-option ${state.service===t?'selected':''}" data-action="service:${i}">${icon(['washer','drop','drop','rotate','volume','power'][i])}<span>${t}</span>${state.service===t?icon('check'):''}</button>`).join('')}</div><div class="home-note">${icon('info')}<span>Check-up starts at <b style="color:#39333f">₹249</b><br>Review the diagnosis and approve the quote before repair.</span></div></div>`;
case 'select':footer=button('Book check-up · ₹249','book');return `<div class="page">${badge('Washing machine repair','purple')}<h1 class="page-title">Tell us a little more</h1><p class="subtitle">A few details help your professional prepare.</p><div class="card"><div class="info-row"><span>Appliance</span><span>Front-load washing machine</span></div><div class="info-row"><span>Brand</span><span>LG</span></div><div class="info-row"><span>Issue</span><span>${esc(state.service==='Not draining'?'Water is not draining':state.service)}</span></div><div class="divider"></div><div class="row between"><span>Inspection charge</span><b>₹249</b></div></div><h3 class="section-title">Anything else you’ve noticed?</h3>${['Water remains inside the drum','Machine displays an error code','Unusual pump noise','Problem started recently'].map((t,i)=>`<label class="checkbox"><input type="checkbox" data-symptom="${i}" ${state.symptoms[i]?'checked':''}>${t}</label>`).join('')}<h3 class="section-title">Choose a convenient visit</h3><div class="chips date-chips">${['12 Oct','13 Oct','14 Oct'].map(t=>`<button class="chip ${state.date===t?'active':''}" data-action="date:${t}">${t==='12 Oct'?'Mon':t==='13 Oct'?'Tue':'Wed'}<br><b>${t}</b></button>`).join('')}</div><div class="chips">${['10:00–11:00 AM','12:00–1:00 PM','3:00–4:00 PM'].map(t=>`<button class="chip ${state.slot===t?'active':''}" data-action="slot:${t}">${t}</button>`).join('')}</div><div class="card purple"><div class="row start">${icon('shield')}<p style="margin:0">The professional will inspect the appliance and share a quotation for your approval before beginning the repair.</p></div></div></div>`;
case 'booking':nav=true;footer=state.submitted?button('Review diagnosis '+icon('chevron'),'go:ready'):button('Mark inspection complete','mark-inspection','secondary');return `<div class="page"><div class="row between">${badge(state.submitted?'Diagnosis ready':'Booking confirmed','green','check')}<span class="tiny muted">UC-WM-28491</span></div><h1 class="page-title" style="margin-top:15px">You’re in good hands</h1><p class="subtitle">LG front-load washing machine · ${esc(state.service)}</p><div class="card">${profile()}<div class="divider"></div><div class="row between small"><span class="muted">${state.submitted?'Inspection complete':'Scheduled arrival'}</span><b>${state.date} · ${state.slot}</b></div><div class="inline-btns" style="margin-top:15px">${button(icon('call')+' Call','contact:call','secondary')}${button(icon('chat')+' Chat','contact:chat','secondary')}</div></div><h3 class="section-title">Your booking, step by step</h3><div class="card timeline">${['Booking confirmed','Professional assigned','Professional arrived','Inspection in progress','Diagnosis ready'].map((t,i)=>`<div class="timeline-step"><span class="dot ${i<(state.submitted?5:3)?'done':i===3&&!state.submitted?'current':''}">${i<(state.submitted?5:3)?icon('check'):''}</span><div><b>${t}</b><div class="tiny muted">${['Your check-up is scheduled','Arjun Kumar is your professional','Professional checked in at 10:35 AM','6 checks to understand the issue','Review the findings before the quote'][i]}</div></div></div>`).join('')}</div><div class="card"><div class="row start">${icon('pin')}<div><b class="small">Service address</b><p>Rahul Mehta<br>Flat 402, Palm Heights, Lokhandwala<br>Andheri West, Mumbai · 400053</p></div></div></div><div class="card purple"><h3>What happens during inspection?</h3><p>Arjun checks the drainage system and records evidence. You’ll see the findings, certainty and an itemised quote before deciding.</p></div>${!state.submitted?'<p class="tiny muted center">Prototype control opens the professional’s required inspection steps.</p>':''}</div>`;
case 'ready':if(!state.submitted)return locked();footer=button('Review diagnosis '+icon('chevron'),'view-diagnosis')+button('Message professional','contact:chat','quiet');return `<div class="page center"><div class="big-success">${icon('check')}</div>${badge('Inspection complete','green')}<h1 class="page-title" style="margin-top:17px">Your diagnosis is ready</h1><p class="subtitle">Arjun has completed 6 diagnostic checks<br>and added supporting evidence.</p><div class="stats" style="text-align:left;margin-top:26px"><div><b>6</b><span>Diagnostic checks completed</span></div><div><b>${state.evidence.length}</b><span>Supporting evidence items</span></div><div><b>1</b><span>${state.certainty.toLowerCase()} finding</span></div><div><b>18 <span>min</span></b><span>Time spent on inspection</span></div></div><div class="card purple" style="text-align:left;margin-top:22px"><div class="row start">${icon('shield')}<p style="margin:0">Understand what was found, see the evidence and choose what happens next. You’re in control.</p></div></div>${profile()}</div>`;
case 'diagnosis':if(!state.submitted)return locked();footer=state.certainty==='Confirmed'?button('View repair quote '+icon('chevron'),'view-quote')+button(icon('spark')+' Ask UC Assist','assist','quiet'):button('Request expert review','expert')+button(icon('spark')+' Ask UC Assist','assist','quiet');return `<div class="page"><div class="row between"><span class="eyebrow">Inspection complete</span>${badge('6 checks · 4 evidence items')}</div><h1 class="page-title">Diagnosis Snapshot</h1><p class="subtitle">See what was checked, what was found and how certain the professional is.</p>${findingCard()}${state.certainty!=='Confirmed'?`<div class="card amber"><h3>What we know — and what we don’t</h3><p><b>Established:</b> Pump output measured at 4 L/min.</p><p><b>Uncertain:</b> Whether low output is caused by blockage or pump wear.</p><p><b>Additional check:</b> Retest output after clearing the drain filter.</p><p><b>Immediate repair:</b> No pump replacement is recommended without further evidence.</p></div>`:''}<div class="row between"><h3 class="section-title">Checks completed</h3><span class="small muted">6 of 6</span></div>${checksCard()}<div class="row between"><h3 class="section-title">Supporting evidence</h3>${badge('Captured on-site','green','camera')}</div>${evidenceCards()}<div class="trust-note">${icon('info')}<span>Evidence is recorded by your professional. Readings and error codes support the inspection and may not identify the exact cause on their own.</span></div>${assistCard()}<h3 class="section-title">Still have a question?</h3><div class="chips">${['Why does the hose need replacement?','Can I continue using the machine?','What happens if I repair it later?','Show me the supporting evidence'].map((q,i)=>`<button class="chip" data-action="ask:${i}">${q}</button>`).join('')}</div></div>`;
case 'quote':if(!state.submitted)return locked();footer=button('Continue to decision '+icon('chevron'),'go:decision')+button(icon('spark')+' Ask about this quote','assist','quiet');return `<div class="page"><div class="eyebrow">Your repair plan</div><h1 class="page-title">Repair quotation</h1><p class="subtitle">Every charge is connected to a finding from your diagnosis.</p>${state.revised?`<div class="card amber"><h3>Your quotation has been updated</h3><p>Old total: ₹1,348 · New total: ${money(total())}<br><b>Change: +₹100</b> · Updated replacement-part price</p><p class="tiny">Your previous approval is no longer valid. Please review and approve this version.</p></div>`:''}${quoteItems()}${totals()}<div class="trust-note">${icon('shield')}<span>Prices follow Urban Company’s service rate card. No additional work will begin without your approval.</span></div>${assistCard(true)}<button class="link" data-action="go:diagnosis">${icon('back')} Back to the Diagnosis Snapshot</button></div>`;
case 'decision':if(!state.submitted)return locked();footer='<div class="caption">Choose the option that’s right for you. Nothing is preselected.</div>';return `<div class="page"><h1 class="page-title">Choose what happens next</h1><p class="subtitle">Your diagnosis and quote are ready.<br>Take a moment. The decision is yours.</p>${state.revised?'<div class="warning">Updated quote · Fresh approval required</div>':''}<div class="card decision-card"><div class="row"><span class="option-icon">${icon('tool')}</span><h3 style="margin:0">Approve repair</h3></div><p>Clean the drain system and replace the damaged outlet hose.</p><div class="row between"><b>${money(total())}</b><span class="small muted">45 min · 30-day warranty</span></div>${button((state.revised?'Approve revised quote · ':'Approve ')+money(total()),'approve','secondary',state.expert==='pending'||state.certainty!=='Confirmed')}</div><div class="card decision-card"><div class="row"><span class="option-icon">${icon('shield')}</span><h3 style="margin:0">Request expert review</h3></div><p>A senior UC expert reviews the diagnosis, evidence and quotation.</p><div class="small muted">Within 15 minutes · Your professional will wait</div>${button('Request expert review','expert','secondary')}</div><div class="card decision-card"><div class="row"><span class="option-icon">${icon('clock')}</span><h3 style="margin:0">Decline repair</h3></div><p>The appliance will not be repaired. Inspection charges may still apply. Your diagnosis stays in booking history.</p>${button('Decline repair','decline','secondary')}</div></div>`;
case 'expert':footer=state.expert==='complete'?button('Approve repair · '+money(total()),'approve','',state.certainty!=='Confirmed')+button('Speak to expert','contact:expert','secondary')+button('Decline repair','decline','quiet'):button('Complete expert review · Demo','expert-complete','secondary');return `<div class="page center"><div class="big-success" style="background:#eee7ff;color:var(--purple)">${icon('shield')}</div>${badge(state.expert==='complete'?'Review complete':'Expert review requested','purple')}<h1 class="page-title" style="margin-top:16px">${state.expert==='complete'?'A second look. More clarity.':'An expert is taking a look'}</h1><p class="subtitle">${state.expert==='complete'?(state.certainty==='Confirmed'?'The diagnosis and quoted work are supported by the submitted checks and evidence.':'The available evidence does not confirm the cause. An additional pump-output test is required before repair approval.'):'Your diagnosis is being reviewed by a UC expert.'}</p><div class="card" style="text-align:left"><div class="row">${icon('file')}<b>What’s being reviewed</b></div><div class="record-line">${icon('check')} 6 diagnostic checks</div><div class="record-line">${icon('check')} Supporting evidence and certainty</div><div class="record-line">${icon('check')} Each repair item and its price</div></div><div class="card purple" style="text-align:left"><p>${icon('clock')} ${state.expert==='complete'?'Review completed by UC senior expert Priya Shah.':'Estimated response: within 15 minutes.'}</p><p>Your professional will wait. No repair will start without your approval.</p></div><p class="tiny muted">Prototype review is simulated and creates no real service request.</p></div>`;
case 'approved':footer=button('View professional’s next step '+icon('chevron'),'switch-tech','secondary');return `<div class="page center"><div class="big-success">${icon('check')}</div>${badge('Repair approved','green')}<h1 class="page-title" style="margin-top:16px">All set, Rahul</h1><p class="subtitle">Arjun has received your approval.<br>He can now begin the agreed repair.</p><div class="card" style="text-align:left"><h3>Approved scope</h3><p>Drain pump and filter cleaning<br>Outlet hose replacement</p><div class="divider"></div><div class="row between"><b>Approved amount</b><b class="price">${money(total())}</b></div><div class="info-row"><span>Estimated repair time</span><span>45 minutes</span></div><div class="info-row"><span>Service warranty</span><span>30 days</span></div>${badge('Quote version '+state.revision,'green')}</div><div class="card purple" style="text-align:left"><p>Any change in the scope or price will need your approval again.</p></div>${profile()}</div>`;
case 'declined':footer=button('View booking history','go:record','secondary');return `<div class="page center"><div class="big-success" style="background:#f1eef6;color:#787181">${icon('check')}</div><h1 class="page-title">Your choice is recorded</h1><p class="subtitle">The repair has been declined. Arjun will not begin work.</p><div class="card" style="text-align:left"><h3>Your inspection is still available</h3><p>The Diagnosis Snapshot and evidence remain in your booking history.</p><div class="info-row"><span>Inspection charge</span><span>₹249</span></div><p class="tiny muted">Inspection charges may still apply.</p>${state.declineReason?`<div class="info-row"><span>Your reason</span><span>${esc(state.declineReason)}</span></div>`:''}</div></div>`;
case 'record':nav=true;footer=button('Book another service','go:home','secondary');return `<div class="page"><div class="row between">${badge(state.completed?'Repair completed':state.customerStatus==='Declined'?'Repair declined':'Service record',state.completed?'green':'',state.completed?'check':null)}<span class="tiny muted">UC-WM-28491</span></div><h1 class="page-title" style="margin-top:13px">Your service record</h1><p class="subtitle">Everything from this visit, in one place.</p><div class="card"><h3>LG front-load washing machine</h3><p class="muted">Water is not draining · Andheri West, Mumbai</p><div class="divider"></div><div class="tiny muted">FINAL DIAGNOSIS</div><p class="bold">Drain filter blockage with reduced pump output and damaged outlet hose.</p><button class="link" data-action="go:diagnosis">View diagnostic checks and evidence ${icon('chevron')}</button></div>${state.completed?`<div class="card green"><div class="small muted">BEFORE</div><p>Water not draining</p><div class="divider"></div><div class="small" style="color:var(--green)">AFTER</div><p class="bold">${icon('check')} Drainage cycle completed successfully</p></div><div class="card"><h3>Work completed</h3><p>Drain pump and filter cleaned<br>Damaged outlet hose replaced<br>Drainage and leak tests passed</p><div class="info-row"><span>Completed</span><span>${esc(state.finishedAt)}</span></div><div class="info-row"><span>Approved quotation / invoice</span><span>${money(total())} · v${state.approvedRevision}</span></div><button class="link" data-action="invoice">${icon('download')} Download invoice</button></div><div class="card purple"><h3>${icon('shield')} 30-day service warranty</h3><p>Valid until ${warrantyExpiry()}. Covers workmanship and the replaced hose for this service.</p><button class="link" data-action="help">Get help with this service</button></div>`:`<div class="card"><p>No repair work has been completed.</p><p>Inspection fee: ₹249</p></div>`}<div class="card">${profile()}</div>${state.completed?`<div class="card center"><h3>Was the issue explained clearly?</h3><p class="muted">How confident do you feel about the explanation?</p><div class="rating" role="group" aria-label="Confidence from 1 to 5">${[1,2,3,4,5].map(n=>`<button data-action="rating:${n}" class="${state.rating===n?'active':''}" aria-pressed="${state.rating===n}">${n}</button>`).join('')}</div><div class="row between tiny muted"><span>Not confident</span><span>Very confident</span></div>${state.rating?'<p class="small" style="color:var(--green)">Thank you. Your feedback is saved.</p>':''}</div>`:''}</div>`;
case 'assigned':footer=button('Start inspection '+icon('chevron'),'go:checklist');return `<div class="page"><div class="row between">${badge('Assigned job','purple')}<span class="tiny muted">UC-WM-28491</span></div><h1 class="page-title" style="margin-top:14px">Washing machine check-up</h1><p class="subtitle">${state.date} · ${state.slot}</p><div class="card"><h3>Rahul Mehta</h3><p>LG front-load washing machine</p><div class="reason"><b>Reported issue</b><br>Water is not draining</div><div class="row start small">${icon('pin')}<span>Flat 402, Palm Heights, Lokhandwala<br>Andheri West, Mumbai · 400053</span></div><div class="inline-btns" style="margin-top:16px">${button(icon('call')+' Call customer','contact:call','secondary')}${button(icon('chat')+' Message','contact:chat','secondary')}</div></div><h3 class="section-title">Reported symptoms</h3><div class="card"><p>Water remains inside the drum<br>Machine displays an error code<br>Problem started recently</p></div><h3 class="section-title">Service history</h3><div class="card"><p>No previous washing-machine repairs on UC.</p><span class="small muted">First-time appliance repair customer</span></div><div class="card purple"><p>Record your checks and evidence. Share your findings and quote before beginning repair.</p></div></div>`;
case 'checklist':footer=button('Continue to evidence '+icon('chevron'),'go:capture','',!allChecks());return `<div class="page">${step(1)}<h1 class="page-title">Guided inspection</h1><p class="subtitle">Complete each required check. Your notes and evidence help the customer understand the finding.</p><div class="row between small"><b>${state.checkStatus.filter((s,i)=>s&&(s!=='Could not verify'||state.checkReasons[i]?.trim().length>5)).length} of 6 required checks completed</b><span class="muted">Drainage issue</span></div><div class="progress-track"><div style="width:${state.checkStatus.filter(Boolean).length/6*100}%"></div></div>${checks.map((c,i)=>`<div class="card tech-check"><div class="row between"><span class="check-name">${i+1}. ${['Inspect drain filter','Test drain pump output','Inspect outlet hose','Check external drain pipe','Check control-panel error','Test drum rotation'][i]}</span>${state.checkStatus[i]?icon('check','check-icon'):''}</div><div class="segmented">${['Passed','Issue found','Could not verify'].map(t=>`<button class="${state.checkStatus[i]===t?'active':''}" data-action="check:${i}:${t}">${t}</button>`).join('')}</div>${state.checkStatus[i]==='Could not verify'?`<label class="field-label" for="reason-${i}">Why couldn’t this be verified? *</label><input id="reason-${i}" class="field" data-reason="${i}" value="${esc(state.checkReasons[i]||'')}" placeholder="Record a specific reason">`:''}<div class="mini-actions"><button data-action="note:${i}">+ Observation</button><button data-action="upload:${i}:photo">+ Photo</button><button data-action="upload:${i}:video">+ Video</button></div><div class="mini-actions"><button data-action="reading:${i}">+ Reading</button><button data-action="code:${i}">+ Error code</button></div>${state.observations[i]?`<p class="tiny muted">${esc(state.observations[i])}</p>`:''}</div>`).join('')}${!allChecks()?'<div class="warning">Complete all checks, or provide a reason for each unverified check, to continue.</div>':''}</div>`;
case 'capture':footer=button('Record finding '+icon('chevron'),'go:finding','',!allChecks());return `<div class="page">${step(2)}<h1 class="page-title">Make the finding visible</h1><p class="subtitle">Evidence from your inspection, linked to the check it supports. Illustrations represent demo captures.</p>${state.evidence.map((e,i)=>`<div class="card"><div class="row start"><button class="evidence-card" data-action="evidence:${i}" style="width:94px;flex-shrink:0"><div class="evidence-art" style="height:74px">${evidenceArt(e)}</div></button><div class="grow"><b class="small">${esc(e.title)}</b><div class="tiny muted">${esc(checks[e.check][0])}<br>${esc(e.time)} · Captured by Arjun</div>${badge(e.clear?'Quality verified':'Evidence unclear',e.clear?'green':'amber')}</div></div><p>${esc(e.description)}</p><div class="mini-actions"><button data-action="retake:${i}">Retake</button><button data-action="remove:${i}">Remove</button><button data-action="unclear:${i}">${e.clear?'Mark unclear':'Confirm clear'}</button></div></div>`).join('')}${button('+ Add another evidence item','upload:0:photo','secondary')}<div class="trust-note">${icon('info')}<span>Confirm that images are in focus and readings are legible. Unclear evidence blocks sharing a confirmed diagnosis.</span></div></div>`;
case 'finding':footer=button('Draft customer summary '+icon('spark'),'generate','',!allChecks()||state.certaintyReason.trim().length<13);return `<div class="page">${step(3)}<h1 class="page-title">Finding & certainty</h1><p class="subtitle">Record your inspection finding. UC Assist will help explain it to the customer.</p><div class="card"><h3>Main finding</h3><p>${state.certainty==='Confirmed'?'Drain filter blockage with reduced pump output and damaged outlet hose.':state.certainty==='Likely'?'Drain pump may be losing efficiency.':'The reported issue could not be reproduced or confirmed.'}</p></div><label class="field-label">How certain is the finding?</label><div class="segmented">${['Confirmed','Likely','Not Verified'].map(t=>`<button class="${state.certainty===t?'active':''}" data-action="certainty:${t}">${t}</button>`).join('')}</div><label class="field-label" for="certaintyReason">Explain your certainty *</label><textarea id="certaintyReason" data-field="certaintyReason">${esc(state.certaintyReason)}</textarea><label class="field-label" for="recommend">Recommended action</label><select id="recommend" data-field="recommend">${['Repair','Monitor and reassess','Additional inspection required','No repair required','Replacement may be more appropriate'].map(t=>`<option ${state.recommend===t?'selected':''}>${t}</option>`).join('')}</select><div class="card ${state.certainty==='Confirmed'?'green':'amber'}"><p>${state.certainty==='Confirmed'?'Confirmed findings need direct inspection, readings or visible evidence.':'Uncertainty must remain visible to the customer. Request additional inspection before recommending unsupported work.'}</p></div></div>`;
case 'summary':footer=button((state.certainty==='Confirmed'?'Create evidence-linked quote ':'Review additional inspection ')+icon('chevron'),state.certainty==='Confirmed'?'go:create-quote':'go:review','',!allChecks()||!state.reviewed||!state.summary);return `<div class="page">${step(4)}<h1 class="page-title">A clearer explanation</h1><p class="subtitle">Your inspection. In language the customer can understand.</p><div class="card purple"><div class="assist-header">${icon('spark')} Drafted with UC Assist</div>${badge('Professional certainty: '+state.certainty,state.certainty==='Confirmed'?'green':'amber')}<label class="field-label" for="summary">Customer-friendly summary · Editable</label><textarea id="summary" data-field="summary" style="min-height:175px">${esc(state.summary)}</textarea><button class="link" data-action="generate" style="margin-top:10px">${icon('rotate')} Regenerate from recorded findings</button></div><h3 class="section-title">UC Assist validation</h3><div class="card">${validations().slice(0,6).map(v=>`<div class="validation-row ${v.ok?'':'fail'}">${icon(v.ok?'check':'info')}${v.label}</div>`).join('')}</div><label class="checkbox"><input type="checkbox" id="reviewed" ${state.reviewed?'checked':''}>I have reviewed this summary and confirm that it accurately represents my inspection.</label><div class="trust-note">${icon('shield')}<span>UC Assist summarises and validates. It does not inspect, diagnose, submit or approve the repair.</span></div></div>`;
case 'create-quote':footer=button('Review before sharing '+icon('chevron'),'quote-create','',!allChecks()||state.links.some(v=>!v));return `<div class="page">${step(5)}<h1 class="page-title">Build the repair quote</h1><p class="subtitle">Add work from the UC rate card. Every item needs a finding, check and supporting evidence.</p>${state.certainty!=='Confirmed'?'<div class="warning">These repair items are unsupported for an uncertain finding. Confirm the finding with additional checks before submitting this quote.</div>':''}${quoteItems(true)}${totals()}${state.links.some(v=>!v)?'<div class="warning">An item has no linked finding. Link both items before continuing.</div>':''}<div class="trust-note">${icon('info')}<span>Any change to the scope or price invalidates earlier customer approval.</span></div></div>`;
case 'review':footer=button('Submit to customer '+icon('chevron'),'submit','',!canSubmit());return `<div class="page">${step(6)}<h1 class="page-title">Ready to share?</h1><p class="subtitle">Preview what Rahul will receive. You are responsible for the diagnosis and final summary.</p>${validations().some(v=>!v.ok)?`<div class="card amber"><h3>Resolve before sharing</h3>${validations().filter(v=>!v.ok).map(v=>`<div class="validation-row fail">${icon('info')}${v.label}</div>`).join('')}</div>`:`<div class="status-banner">${icon('check')} All checks passed · Ready for your review</div>`}<div class="row between"><h3 class="section-title">Diagnosis Snapshot</h3><button class="link" data-action="go:finding">Edit diagnosis</button></div>${findingCard()}<p class="small muted">6 checks completed · ${state.evidence.length} evidence items</p>${evidenceCards()}<button class="link" data-action="go:capture" style="margin-top:10px">Edit evidence</button>${assistCard()}<button class="link" data-action="go:summary">Edit explanation</button><div class="row between"><h3 class="section-title">Evidence-Linked Quote</h3><button class="link" data-action="go:create-quote">Edit quotation</button></div>${state.certainty==='Confirmed'?quoteItems()+totals():'<div class="card amber"><h3>No repair quotation recommended</h3><p>Share the uncertain finding and request additional inspection or expert review. The inspection fee is ₹249.</p></div>'}<div class="card"><h3>Customer decision options</h3><p>${state.certainty==='Confirmed'?'Approve repair · Request expert review · Decline repair':'Request expert review · Additional inspection required'}</p><p class="tiny muted">You cannot begin until the customer approves this quote.</p></div></div>`;
case 'waiting':footer=canRepair()?button(state.repairStarted?'Complete repair':'Start repair',state.repairStarted?'complete':'start-repair'):button('Start repair','start-repair','',true);return `<div class="page">${badge(state.completed?'Repair completed':state.approved?'Repair approved':state.customerStatus==='Declined'?'Repair declined':'Awaiting customer',state.approved||state.completed?'green':'purple')}<h1 class="page-title" style="margin-top:15px">${state.completed?'The job is complete':state.approved?(state.repairStarted?'Repair in progress':'You’re cleared to begin'):'Shared with Rahul'}</h1><p class="subtitle">${state.completed?'The service record and invoice are available to Rahul.':state.approved?'Repair approval received for the scope below.':(state.certainty==='Confirmed'?'Diagnosis and quotation shared with Rahul. Wait for his decision before starting work.':'Inspection findings shared with Rahul. Additional inspection is required; no repair quotation is recommended.')}</p><div class="card"><div class="row between"><h3 style="margin:0">Customer status</h3>${badge(state.customerStatus,state.approved?'green':'purple')}</div><div class="info-row"><span>${state.certainty==='Confirmed'?'Shared quotation':'Shared diagnosis'}</span><span>Version ${state.revision}</span></div><div class="info-row"><span>${state.certainty!=='Confirmed'?'Next step':state.approved?'Approved amount':'Total amount'}</span><b>${state.certainty==='Confirmed'?money(total()):'Additional inspection required'}</b></div>${state.approved?'<div class="divider"></div><p>Approved scope:<br>Drain pump and filter cleaning<br>Outlet hose replacement</p>':''}</div>${state.expert==='pending'?'<div class="card amber"><h3>Expert review requested</h3><p>Wait for the review and fresh customer approval.</p><button class="link" data-action="review-response">Respond to expert review</button></div>':''}${state.repairStarted?'<div class="card green"><h3>Repair started</h3><p>Clean the drainage system, replace the hose and run a drainage and leak test.</p></div>':''}<div class="card"><h3>Stay available</h3><p>Answer questions and clarify evidence without changing the customer’s decision.</p><div class="mini-actions"><button data-action="contact:chat">Message customer</button><button data-action="clarify">Clarify finding</button></div></div>${state.certainty==='Confirmed'&&!state.completed&&!state.repairStarted?button('Revise quotation','revise-modal','secondary'):''}${button('Open customer view '+icon('chevron'),'switch-customer','quiet')}${state.completed?button('View customer service record','customer-record','secondary'):''}<div class="trust-note">${icon('shield')}<span>${state.approved?'If the price or scope changes, this approval is invalidated.':'Only a customer approval enables Start repair.'}</span></div></div>`;
default:return locked();}}
function locked(){footer=button('Open professional inspection','switch-tech','secondary');return `<div class="page empty">${icon('shield')}<h1 class="page-title">Waiting for the inspection</h1><p class="subtitle">Arjun needs to complete the required checks, review the summary and submit the diagnosis before Rahul can review or approve the repair.</p></div>`}
function warrantyExpiry(){let d=new Date(state.finishedISO||Date.now());d.setDate(d.getDate()+30);return d.toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'})}
const mapStates=[['Booking confirmed','booking'],['Inspection checklist','checklist'],['AI-assisted technician summary','summary'],['Diagnosis ready','ready'],['Confirmed diagnosis','confirmed'],['Likely diagnosis','likely'],['Evidence-Linked Quote','quote'],['Revised quotation','revised'],['Expert review','expert'],['Repair approved','approved'],['Service completed','record']];
function render(){const body=page();const titles={home:'Andheri West, Mumbai',select:'Washing machine repair',booking:'Your booking',ready:'Inspection completed',diagnosis:'Diagnosis Snapshot',quote:'Repair quotation',decision:'Your decision',expert:'Expert review',approved:'Repair approved',record:'Service record',declined:'Your booking',assigned:'Assigned job',checklist:'Inspection checklist',capture:'Supporting evidence',finding:'Record finding',summary:'UC Assist summary','create-quote':'Create quotation',review:'Review & submit',waiting:'Job status'};$('#app').innerHTML=`<main class="workspace"><aside class="intro"><div class="brand"><div class="logo">UC</div><div>Urban<br>Company</div></div><div class="eyebrow">A little clarity goes a long way</div><h1>Understand<br>the diagnosis.<br>Own the decision.</h1><p>A familiar service experience, with a clearer view of what’s wrong and why a repair is needed.</p><div style="margin-top:32px"><div class="feature">${icon('list')}<span>See what was checked</span></div><div class="feature">${icon('camera')}<span>Review the supporting evidence</span></div><div class="feature">${icon('shield')}<span>Approve with confidence</span></div></div><div class="footnote">UC Diagnosis Trust Layer<br><span class="muted">Connected prototype · Capstone edition</span></div></aside><div><section class="device" aria-label="${state.role==='customer'?'Customer':'Technician'} app"><div class="statusbar"><span>9:41</span><div class="status-icons">${icon('signal')}${icon('wifi')}${icon('battery')}</div></div><header class="topbar">${state.screen==='home'?icon('pin'):`<button class="icon-btn" data-action="back" aria-label="Go back">${icon('back')}</button>`}<h2>${titles[state.screen]||'UC Diagnosis'}${state.screen==='home'?'<div class="sub">Mumbai · 400053</div>':state.role==='technician'?'<div class="sub">UC Partner · Arjun Kumar</div>':''}</h2><button class="help" data-action="help">Help</button></header><div class="content">${body}</div>${footer?`<div class="footer">${footer}</div>`:''}${nav?`<nav class="bottom-nav" aria-label="App navigation"><button data-action="go:home" class="${state.screen==='home'?'active':''}">${icon('home')}Home</button><button data-action="bookings" class="${state.screen!=='home'?'active':''}">${icon('calendar')}Bookings</button><button data-action="profile">${icon('user')}Profile</button></nav>`:''}</section><div class="phone-caption">${state.role==='customer'?'Customer':'Professional'} experience · Live shared booking state</div></div><aside class="map ${mapOpen?'open':''}" aria-label="Prototype Map"><div class="row between"><div><div class="eyebrow">Explore the experience</div><div class="map-title" style="margin-top:5px">Prototype Map</div></div><button class="icon-btn map-close" data-action="map" aria-label="Close map">${icon('close')}</button></div><div class="role-toggle"><button class="${state.role==='customer'?'active':''}" data-action="role:customer">Customer View</button><button class="${state.role==='technician'?'active':''}" data-action="role:technician">Technician View</button></div><div class="eyebrow">Jump to a demo state</div><div class="map-links">${mapStates.map(([t,id],i)=>`<button data-action="demo:${id}" class="${id===state.screen||(id==='confirmed'&&state.screen==='diagnosis'&&state.certainty==='Confirmed')||(id==='likely'&&state.screen==='diagnosis'&&state.certainty==='Likely')?'active':''}"><span class="number">${String(i+1).padStart(2,'0')}</span>${t}</button>`).join('')}</div><p>Jump links load prepared demo data. To experience the full journey, switch roles and complete each step.</p><div class="map-status"><span class="live-dot"></span> Shared booking · ${state.approved?'Approved':state.submitted?'Submitted':'Inspection pending'}</div><button class="link" data-action="reset" style="margin-top:13px;font-size:9px">${icon('rotate')} Reset prototype</button></aside></main><button class="map-mobile" data-action="map">${icon('list')} Prototype Map</button>`;save();}
function modal(title,body,kind='info'){sheet=kind;$('#overlay').innerHTML=`<div class="modal-backdrop" data-dismiss="true"><section class="sheet" role="dialog" aria-modal="true" aria-label="${esc(title)}" tabindex="-1"><div class="sheet-handle"></div><div class="sheet-header"><h2>${title}</h2><button class="icon-btn" data-action="close" aria-label="Close dialog">${icon('close')}</button></div>${body}</section></div>`;$('.sheet').focus()}
function close(){sheet=null;$('#overlay').innerHTML='';$('.topbar button')?.focus()}
function viewEvidence(i){const e=state.evidence[i];if(!e)return toast('This evidence has been removed.');modal(e.title,`<div class="evidence-art">${evidenceArt(e)}</div><div class="chips">${badge(e.clear?'Quality verified':'Evidence unclear',e.clear?'green':'amber','camera')}${badge('Illustrative demo capture')}</div><p>${esc(e.description)}</p><div class="info-row"><span>Related check</span><span>${esc(checks[e.check][0])}</span></div><div class="info-row"><span>Captured</span><span>${esc(e.time)} · By Arjun Kumar</span></div><div class="card"><b class="small">What this establishes</b><p>${esc(e.description)}</p>${e.limitation?`<p class="muted small">${esc(e.limitation)}</p>`:''}</div><p class="tiny muted">Prepared evidence illustrates the prototype scenario. Uploaded files remain in this browser session.</p>`,'evidence')}
const questions=['Explain this diagnosis simply','Why is this repair required?','Which evidence supports the quote?','Can I delay this repair?','Should I repair or replace the machine?','What is covered by the warranty?'];
function assist(){modal('Ask UC Assist',`<div class="row between"><span class="small muted">Clarity from your inspection</span><div class="chips" style="margin:0">${['English','हिन्दी'].map(t=>`<button class="chip ${assistLanguage===t?'active':''}" data-action="lang:${t}">${t}</button>`).join('')}</div></div>${assistQuestion!==null?`<div class="answer"><div class="assist-header">${icon('spark')} ${esc(questions[assistQuestion]||assistQuestion)}</div>${assistAnswer(assistQuestion)}<div class="reviewed">${icon('shield')} Based on Arjun’s recorded checks</div></div>`:''}<div class="small bold" style="margin:18px 0 8px">${assistLanguage==='English'?'You might want to ask':'आप पूछ सकते हैं'}</div>${questions.map((q,i)=>`<button class="question" data-action="assist-q:${i}">${assistLanguage==='English'?q:['इस जाँच को सरल भाषा में समझाएँ','यह मरम्मत क्यों ज़रूरी है?','कौन सा सबूत कीमत का समर्थन करता है?','क्या मैं मरम्मत टाल सकता हूँ?','मरम्मत कराऊँ या मशीन बदलूँ?','वारंटी में क्या शामिल है?'][i]}${icon('chevron','chevron')}</button>`).join('')}<div class="trust-note">${icon('info')}<span>UC Assist explains the professional’s findings. It has not inspected your appliance. For an independent check, request expert review.</span></div>`,'assist')}
function assistAnswer(q){const hindi=assistLanguage!=='English';if(state.certainty!=='Confirmed'||state.evidence.some(e=>!e.clear)||![0,1,2,4].every(i=>state.evidence.some(e=>e.check===i))){return (hindi?'जाँच से पानी का प्रवाह कम पाया गया है, लेकिन कारण की पुष्टि नहीं हुई है। उपलब्ध सबूत अधूरे या अस्पष्ट हैं। मरम्मत का निर्णय लेने से पहले UC विशेषज्ञ की समीक्षा का अनुरोध करें।':'The recorded checks show reduced drainage output, but the cause is not fully confirmed or the supporting evidence is incomplete. Request expert review before deciding on repair.')+`<br><button class="link" data-action="expert">${hindi?'विशेषज्ञ समीक्षा का अनुरोध करें':'Request expert review'}</button>`}const en=[summaryConfirmed,'The hose replacement is recommended because Arjun recorded a visible crack near the connector. The cleaning is linked to the blocked filter and reduced pump output. A damaged hose may leak during future wash cycles.','The filter photo and pump-output reading support the cleaning. The damaged-hose photo supports the hose replacement. There is no pump replacement on this quote.','Arjun recorded a blocked filter and damaged hose. Drainage may remain affected until repaired. Ask Arjun about use before continuing a cycle; choose expert review if you would like another opinion.','The inspection supports the quoted cleaning and hose replacement. Appliance age and replacement cost were not recorded, so UC Assist cannot compare repair and replacement reliably. A UC expert can help review your options.','The 30-day service warranty covers workmanship and the outlet hose replaced in this visit. It does not cover unrelated faults or additional work. Your saved service record includes the expiry date.'];const hi=['फ़िल्टर में रुकावट है और पानी निकासी की नली क्षतिग्रस्त है। पंप काम कर रहा है, लेकिन उसका प्रवाह अपेक्षा से कम है। यह अर्जुन की दर्ज की गई जाँच पर आधारित है।','अर्जुन ने नली के कनेक्टर के पास दरार दर्ज की है। फ़िल्टर की रुकावट और कम पंप प्रवाह के कारण सफ़ाई सुझाई गई है। क्षतिग्रस्त नली से पानी रिस सकता है।','फ़िल्टर की तस्वीर और पंप प्रवाह की रीडिंग सफ़ाई का समर्थन करती हैं। नली की तस्वीर नली बदलने का समर्थन करती है। इस कीमत में पंप बदलना शामिल नहीं है।','अर्जुन ने फ़िल्टर में रुकावट और क्षतिग्रस्त नली दर्ज की है। मरम्मत होने तक पानी निकासी प्रभावित रह सकती है। मशीन चलाने से पहले अर्जुन से पूछें; दूसरे मत के लिए विशेषज्ञ समीक्षा चुनें।','जाँच सफ़ाई और नली बदलने का समर्थन करती है। मशीन की उम्र और नई मशीन की कीमत दर्ज नहीं है, इसलिए भरोसेमंद तुलना उपलब्ध नहीं है। UC विशेषज्ञ विकल्पों की समीक्षा कर सकते हैं।','30 दिन की सेवा वारंटी इस काम की गुणवत्ता और बदली गई नली को कवर करती है। असंबंधित खराबियाँ या अतिरिक्त काम शामिल नहीं हैं। सेवा रिकॉर्ड में समाप्ति तिथि उपलब्ध है।'];return (hindi?hi[q]:en[q])+`<br><button class="link" style="margin-top:9px" data-action="linked:${q===1?1:0}">${icon('camera')} ${hindi?'संबंधित सबूत देखें':'View supporting evidence'}</button>`}
function prepared(){state.booked=true;state.checkStatus=checks.map(c=>c[2]);state.checkReasons={};state.certainty='Confirmed';state.certaintyReason=base().certaintyReason;state.recommend='Repair';state.evidence=structuredClone(evidenceSeed);state.summary=summaryConfirmed;state.reviewed=true;state.quoteCreated=true;state.links=[true,true];state.prices=[499,600];state.submitted=true;state.approved=false;state.approvedRevision=null;state.completed=false;state.repairStarted=false;state.revised=false;state.revision=1;state.expert='none';state.customerStatus='Not viewed'}
function demo(id){const role=state.role;prepared();if(id==='booking'){state.submitted=false;state.checkStatus=base().checkStatus;state.screen=role==='customer'?'booking':'assigned'}else if(id==='checklist'){state.submitted=false;state.checkStatus=base().checkStatus;state.screen=role==='technician'?'checklist':'booking'}else if(id==='summary'){state.submitted=false;state.screen=role==='technician'?'summary':'booking'}else if(id==='ready')state.screen=role==='customer'?'ready':'waiting';else if(id==='confirmed')state.screen=role==='customer'?'diagnosis':'review';else if(id==='likely'){state.certainty='Likely';state.summary=summaryLikely;state.certaintyReason='Available evidence suggests reduced pump efficiency, but an additional test is required.';state.recommend='Additional inspection required';state.quoteCreated=false;state.screen=role==='customer'?'diagnosis':'finding'}else if(id==='quote')state.screen=role==='customer'?'quote':'create-quote';else if(id==='revised'){state.prices[1]=700;state.revision=2;state.revised=true;state.screen=role==='customer'?'quote':'waiting'}else if(id==='expert'){state.expert='pending';state.customerStatus='Expert review requested';state.screen=role==='customer'?'expert':'waiting'}else if(id==='approved'){state.approved=true;state.approvedRevision=state.revision;state.customerStatus='Approved';state.screen=role==='customer'?'approved':'waiting'}else if(id==='record'){state.approved=true;state.approvedRevision=state.revision;state.completed=true;state.customerStatus='Approved';finishTime();state.screen=role==='customer'?'record':'waiting'}mapOpen=false;save();render();toast('Prepared demo state loaded. Role selection preserved.');}
function invalidate(){if(state.submitted||state.approved){state.submitted=false;state.approved=false;state.approvedRevision=null;state.repairStarted=false;state.customerStatus='Not viewed';state.expert='none';state.revision++;toast('Changed inspection: resubmit and obtain fresh approval.')}state.reviewed=false;save()}
function finishTime(){state.finishedISO=new Date().toISOString();state.finishedAt=new Date().toLocaleString('en-IN',{day:'numeric',month:'short',year:'numeric',hour:'numeric',minute:'2-digit'})}
async function action(a){const [kind,arg,arg2]=a.split(':');if(kind==='go'){if(['quote','decision','approved','ready','diagnosis'].includes(arg)&&!state.submitted)return toast('The professional must submit the diagnosis first.');if(arg==='approved'&&!state.approved)return toast('Fresh customer approval is required.');if(arg==='quote'&&state.certainty!=='Confirmed')return toast('Additional inspection is required for this finding.');return go(arg)}switch(kind){
case 'back':back();break;
case 'map':mapOpen=!mapOpen;render();break;
case 'role':state.role=arg;state.history=[];state.screen=arg==='technician'?(state.submitted?'waiting':'assigned'):(state.completed?'record':state.customerStatus==='Declined'?'declined':state.approved?'approved':state.expert==='pending'?'expert':state.submitted?'ready':state.booked?'booking':'home');render();break;
case 'service':state.service=['Washing machine check-up','Water leakage','Not draining','Not spinning','Unusual noise','Not powering on'][Number(arg)];if(state.service==='Not draining')go('select');else render();break;
case 'date':state.date=arg;render();break;
case 'slot':state.slot=arg;render();break;
case 'book':state.booked=true;go('booking');toast('Check-up booked. Arjun is assigned to your visit.');break;
case 'bookings':go(state.completed?'record':state.booked?'booking':'home');if(!state.booked)toast('Book a check-up to see your booking here.');break;
case 'profile':modal('Your profile',`<div class="card"><h3>Rahul Mehta</h3><p>Andheri West, Mumbai</p><p class="muted">Your appliance service details stay in booking history.</p></div>${button('View bookings','bookings','secondary')}`);break;
case 'mark-inspection':modal('Complete the professional’s inspection',`<p>The diagnosis can only be shared after all checks are complete, evidence is clear and Arjun has reviewed the summary.</p><p class="muted small">This control takes you to the connected technician workflow.</p>${button('Open inspection checklist','inspection-switch')}`);break;
case 'inspection-switch':close();state.role='technician';go('checklist');break;
case 'view-diagnosis':state.customerStatus='Diagnosis viewed';go('diagnosis');break;
case 'view-quote':state.customerStatus='Quote viewed';go('quote');break;
case 'expand':expanded.has(Number(arg))?expanded.delete(Number(arg)):expanded.add(Number(arg));renderKeepingScroll();break;
case 'quote-expand':quoteExpanded.has(Number(arg))?quoteExpanded.delete(Number(arg)):quoteExpanded.add(Number(arg));renderKeepingScroll();break;
case 'evidence':viewEvidence(Number(arg));break;
case 'linked':{const ids=state.evidence.map((e,i)=>({e,i})).filter(({e})=>Number(arg)===0?[0,1].includes(e.check):e.check===2);modal('Evidence behind this repair',ids.length?ids.map(({e,i})=>`<button class="question" data-action="evidence:${i}"><span><b>${esc(e.title)}</b><br><span class="tiny muted">${esc(e.description)}</span></span>${icon('chevron')}</button>`).join(''):'<p>Supporting evidence is missing. Request expert review.</p>');break;}
case 'certainty-info':modal('What does '+state.certainty+' mean?',`<div class="card ${state.certainty==='Confirmed'?'green':'amber'}"><p>${state.certainty==='Confirmed'?'Confirmed means the finding is supported by direct inspection, readings or visible evidence.':state.certainty==='Likely'?'Likely means the available evidence suggests a cause, but additional checks are needed to confirm it.':'Not Verified means the issue could not be reproduced or confirmed during the visit.'}</p></div><p class="small muted">Certainty is selected and explained by the professional.</p>`);break;
case 'assist':assistQuestion=null;assist();break;
case 'ask':assistQuestion=[1,3,3,2][Number(arg)];assist();break;
case 'assist-q':assistQuestion=Number(arg);assist();break;
case 'lang':assistLanguage=arg;assist();break;
case 'check':invalidate();state.checkStatus[Number(arg)]=arg2;renderKeepingScroll();break;
case 'note':case 'reading':case 'code':modal(kind==='note'?'Add observation':kind==='reading'?'Add meter reading':'Record error code',`<label class="field-label">Related check</label><div class="small">${checks[Number(arg)][0]}</div><label class="field-label" for="capture-note">${kind==='reading'?'Measured value, unit and reference range':kind==='code'?'Error code and observation':'Written observation'}</label><textarea id="capture-note" placeholder="${kind==='reading'?'e.g. 4 L/min; expected 8–12 L/min':kind==='code'?'e.g. OE drainage error':'Describe what you found'}">${esc(state.observations[arg]||'')}</textarea>${button('Save '+(kind==='note'?'observation':'evidence'),'save-note:'+arg+':'+kind)}`);break;
case 'save-note':{let val=$('#capture-note').value.trim();if(val.length<3)return toast('Enter an observation before saving.');invalidate();state.observations[arg]=val;if(arg2!=='note')state.evidence.push({title:arg2==='reading'?'Additional meter reading':'Recorded error code',description:val,check:Number(arg),clear:true,time:new Date().toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'}),type:arg2==='reading'?'reading':'code'});close();renderKeepingScroll();toast('Inspection evidence saved.');break;}
case 'upload':case 'retake':{const idx=kind==='retake'?Number(arg):null;const e=idx===null?null:state.evidence[idx];modal(idx===null?'Add inspection evidence':'Retake evidence',`<label class="field-label" for="e-check">Related diagnostic check</label><select id="e-check">${checks.map((c,i)=>`<option value="${i}" ${i===(e?.check??Number(arg))?'selected':''}>${c[0]}</option>`).join('')}</select><label class="field-label" for="e-title">What does the evidence show?</label><input class="field" id="e-title" placeholder="Describe the visible issue" value="${esc(e?.description||'')}"><label class="field-label">${arg2==='video'?'Short video':'Photo or short video'}</label><label class="upload-label">${icon('camera')} Select a file<input id="e-file" type="file" accept="image/*,video/*"></label><div id="file-status" class="tiny muted" style="margin-top:8px">Files stay in your browser. Maximum 3 MB.</div><label class="checkbox"><input id="e-clear" type="checkbox">I confirm the evidence is clear and the relevant detail is visible.</label>${button('Save evidence','save-evidence:'+(idx===null?'new':idx))}`,'upload');break;}
case 'save-evidence':{const file=$('#e-file').files[0],description=$('#e-title').value.trim(),check=Number($('#e-check').value),clear=$('#e-clear').checked;if(!file||!description)return toast('Select a file and describe what it shows.');if(file.size>3*1024*1024)return toast('Please choose a file smaller than 3 MB.');if(!/^image\/|^video\//.test(file.type))return toast('Choose an image or video.');const reader=new FileReader();reader.onload=()=>{invalidate();const e={title:checks[check][0]+' evidence',description,check,clear,time:new Date().toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'}),type:file.type.startsWith('video')?'video':'photo',url:reader.result};if(arg==='new')state.evidence.push(e);else state.evidence[Number(arg)]=e;close();renderKeepingScroll();toast('Evidence added to this inspection.');};reader.readAsDataURL(file);break;}
case 'remove':invalidate();state.evidence.splice(Number(arg),1);renderKeepingScroll();toast('Evidence removed.');break;
case 'unclear':invalidate();state.evidence[Number(arg)].clear=!state.evidence[Number(arg)].clear;renderKeepingScroll();break;
case 'certainty':invalidate();state.certainty=arg;state.certaintyReason=arg==='Confirmed'?base().certaintyReason:arg==='Likely'?'Available evidence suggests reduced pump efficiency, but an additional test is required.':'The reported issue could not be reproduced or confirmed during the visit.';state.recommend=arg==='Confirmed'?'Repair':'Additional inspection required';state.summary='';state.quoteCreated=false;render();break;
case 'generate':if(busy)return;if(!allChecks())return toast('Complete all diagnostic checks first.');busy=true;state.reviewed=false;state.summary='';go('summary');$('#summary').value='Generating a draft from your recorded checks…';$('#summary').disabled=true;await new Promise(r=>setTimeout(r,700));state.summary=state.certainty==='Confirmed'?summaryConfirmed:state.certainty==='Likely'?summaryLikely:summaryUnverified;state.reviewed=false;busy=false;render();toast('Draft generated. Review it before sharing.');break;
case 'quote-create':if(!allChecks()||state.links.some(v=>!v))return toast('Complete checks and link every quote item.');state.quoteCreated=true;go('review');break;
case 'submit':if(!canSubmit())return toast('Resolve the validation warnings before submitting.');state.submitted=true;state.customerStatus='Not viewed';state.approved=false;state.approvedRevision=null;go('waiting');toast(state.certainty==='Confirmed'?'Diagnosis and quotation shared with Rahul.':'Diagnosis shared with Rahul. Additional inspection required.');break;
case 'approve':if(!state.submitted||state.certainty!=='Confirmed'||state.expert==='pending'||state.role!=='customer')return toast('Customer approval requires a submitted, supported quote.');state.approved=true;state.approvedRevision=state.revision;state.customerStatus='Approved';close();go('approved');toast('Approval sent to Arjun.');break;
case 'expert':if(!state.submitted)return toast('Submit the professional’s findings first.');state.expert='pending';state.customerStatus='Expert review requested';state.approved=false;state.approvedRevision=null;close();state.role='customer';go('expert');toast('Expert review requested. Arjun will wait.');break;
case 'expert-complete':state.expert='complete';render();toast('Demo expert review completed. Fresh approval is required.');break;
case 'decline':if(!state.submitted)return toast('The professional must submit the diagnosis first.');modal('Decline this repair',`<p>The appliance will not be repaired. Inspection charges may still apply. Your diagnosis remains in booking history.</p><label class="field-label">Reason (optional)</label><div class="decline-reasons">${['Repair is too expensive','I need time to decide','I want another opinion','I prefer replacement','Other'].map(t=>`<label><input type="radio" name="decline-reason" value="${t}">${t}</label>`).join('')}</div>${button('Confirm decline','confirm-decline','secondary')}${button('Keep reviewing','close','quiet')}`);break;
case 'confirm-decline':state.declineReason=$('input[name="decline-reason"]:checked')?.value||'';state.customerStatus='Declined';state.approved=false;state.approvedRevision=null;close();go('declined');toast('Arjun has been notified of your decision.');break;
case 'switch-tech':state.role='technician';go(state.submitted?'waiting':'assigned');break;
case 'switch-customer':state.role='customer';go(state.completed?'record':state.approved?'approved':state.customerStatus==='Declined'?'declined':state.expert==='pending'?'expert':state.submitted?'ready':'booking');break;
case 'customer-record':state.role='customer';go('record');break;
case 'revise-modal':modal('Revise quotation',`<p>Updated replacement-part price: <b>₹700</b></p><div class="card amber"><div class="info-row"><span>Old total</span><span>${money(total())}</span></div><div class="info-row"><span>New total</span><span>₹1,448</span></div><p>Change: +₹100 · Updated replacement-part price</p></div><p class="small muted">Sharing this revised quote invalidates previous approval. Rahul must review and approve it again.</p>${button('Share revised quotation','revise')}`);break;
case 'revise':if(!state.submitted||state.repairStarted)return toast('Revision unavailable at this stage.');state.prices[1]=700;state.revised=true;state.revision++;state.approved=false;state.approvedRevision=null;state.customerStatus='Not viewed';state.expert='none';close();render();toast('Revised quotation shared. Previous approval cleared.');break;
case 'start-repair':if(!canRepair())return toast('Wait for approval of the current quote.');state.repairStarted=true;render();toast('Repair started for the approved scope.');break;
case 'complete':if(!canRepair()||!state.repairStarted)return toast('Start the approved repair first.');modal('Complete the service',`<p>Confirm the agreed work and final test.</p>${['Drain pump and filter cleaned','Damaged outlet hose replaced','Drainage cycle completed successfully','Connections tested with no leakage'].map(t=>`<label class="checkbox"><input class="finish-check" type="checkbox">${t}</label>`).join('')}${button('Confirm repair completed','confirm-complete')}`);break;
case 'confirm-complete':if(![...document.querySelectorAll('.finish-check')].every(e=>e.checked))return toast('Confirm all repair and test steps.');state.completed=true;finishTime();close();render();toast('Service completed. Record and invoice saved for Rahul.');break;
case 'rating':state.rating=Number(arg);renderKeepingScroll();toast('Thank you for your feedback.');break;
case 'invoice':{if(!state.completed)return toast('The invoice is available after completion.');const text=`URBAN COMPANY — PROTOTYPE INVOICE\nDemo invoice · Not a tax invoice\nBooking: UC-WM-28491\nCustomer: Rahul Mehta\nAppliance: LG front-load washing machine\nTechnician: Arjun Kumar\nCompleted: ${state.finishedAt}\n\nDrain pump and filter cleaning: ${money(state.prices[0])}\nOutlet hose replacement: ${money(state.prices[1])}\nInspection fee: ₹249\nTotal: ${money(total())}\nApproved quote version: ${state.approvedRevision}\nWarranty: 30 days, valid until ${warrantyExpiry()}\n\nBefore: Water not draining\nAfter: Drainage cycle completed successfully\n`;const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download='UC-WM-28491-demo-invoice.txt';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Demo invoice downloaded.');break;}
case 'review-response':case 'clarify':modal(kind==='clarify'?'Clarify your finding':'Respond to expert review',`<p class="small muted">Add a clarification to the existing inspection. A change to findings requires resubmission.</p><textarea id="clarification" placeholder="Explain the check or evidence…"></textarea>${button('Save clarification','save-clarification')}`);break;
case 'save-clarification':{let t=$('#clarification').value.trim();if(!t)return toast('Enter a clarification first.');state.clarification=t;close();toast('Clarification saved with the booking.');break;}
case 'contact':modal(arg==='call'?'Call professional':arg==='expert'?'Speak to the expert':'Booking messages',`<div class="card"><h3>${arg==='expert'?'Priya Shah · UC senior expert':state.role==='technician'?'Rahul Mehta':'Arjun Kumar'}</h3><p>${arg==='call'?'Call controls are simulated in this prototype.':arg==='expert'?'Your recorded checks and evidence are available for discussion.':'Hello! I’m available to explain the checks and the proposed repair.'}</p></div>${arg!=='call'?`<label class="field-label" for="message">Your message</label><textarea id="message" placeholder="Ask a question about the inspection"></textarea>${button('Send demo message','send-message')}`:button('Simulate call','demo-call','secondary')}<p class="tiny muted">Demo only. No real call or message is sent.</p>`);break;
case 'send-message':if(!$('#message').value.trim())return toast('Enter your message.');state.messages=[...(state.messages||[]),$('#message').value.trim()];close();toast('Demo message saved to this booking.');break;
case 'demo-call':close();toast('Demo call connected.');break;
case 'help':modal('We’re here to help',`<div class="card"><h3>Help with your appliance service</h3><p>Review the diagnosis, ask about evidence or request an expert review before approving.</p></div>${button('Ask UC Assist','assist','secondary')}${state.submitted?button('Request expert review','expert','secondary'):button('View booking','go:booking','secondary')}<p class="tiny muted">This is a clickable prototype. No real booking or payment is made.</p>`);break;
case 'demo':demo(arg);break;
case 'reset':modal('Reset the prototype?',`<p>This clears the demo booking and returns to the beginning of the customer journey.</p>${button('Reset and start over','confirm-reset')}${button('Keep current session','close','quiet')}`);break;
case 'confirm-reset':state=base();close();expanded.clear();quoteExpanded.clear();render();toast('Prototype reset.');break;
case 'close':close();break;
}save()}
function renderKeepingScroll(){const y=$('.content')?.scrollTop||0;render();$('.content').scrollTop=y}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b&&!b.disabled){if(sheet&&b.dataset.action.startsWith('go:'))close();action(b.dataset.action)}else if(e.target.matches('[data-dismiss]'))close()});
document.addEventListener('change',e=>{const t=e.target;if(t.dataset.symptom!==undefined){state.symptoms[Number(t.dataset.symptom)]=t.checked;save()}if(t.id==='reviewed'){state.reviewed=t.checked;renderKeepingScroll()}if(t.dataset.link!==undefined){invalidate();state.links[Number(t.dataset.link)]=t.checked;renderKeepingScroll()}if(t.dataset.price!==undefined){const n=Number(t.value);if(!Number.isInteger(n)||n<1||n>99999){toast('Enter a whole price between ₹1 and ₹99,999.');return renderKeepingScroll()}invalidate();state.prices[Number(t.dataset.price)]=n;state.quoteCreated=false;renderKeepingScroll()}if(t.dataset.field==='recommend'){invalidate();state.recommend=t.value;save()}if(t.id==='e-file')$('#file-status').textContent=t.files[0]?t.files[0].name:'No file selected';});
document.addEventListener('input',e=>{const t=e.target;if(t.dataset.reason!==undefined){state.checkReasons[t.dataset.reason]=t.value;save();const b=$('.footer .btn');if(b)b.disabled=!allChecks()}if(t.dataset.field&&t.dataset.field!=='recommend'){invalidate();state[t.dataset.field]=t.value;if(t.dataset.field==='summary')state.reviewed=false;save();if(t.dataset.field==='certaintyReason'){const b=$('.footer .btn');if(b)b.disabled=!allChecks()||state.certaintyReason.trim().length<13}if(t.dataset.field==='summary'){const c=$('#reviewed');if(c)c.checked=false;const b=$('.footer .btn');if(b)b.disabled=true}}if(t.id==='search'){const q=t.value.toLowerCase();document.querySelectorAll('.service-option').forEach(b=>b.hidden=!b.textContent.toLowerCase().includes(q))}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')close();if(e.key==='Tab'&&sheet){const f=[...$('.sheet').querySelectorAll('button,input,textarea,select,a[href]')].filter(n=>!n.disabled&&n.getClientRects().length);if(f.length){if(e.shiftKey&&document.activeElement===f[0]){e.preventDefault();f.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===f.at(-1)){e.preventDefault();f[0].focus()}}}});
render();
